const req = { user: null, path: '/me' };
const trace = [];

function auth(req, next) {
  trace.push('auth:in');
  req.user = 'alice';
  next();
  trace.push('auth:out');
}
function logger(req, next) {
  trace.push('log:in');
  next();
  trace.push('log:out');
}
function handler(req, next) {
  trace.push('handler(user=' + req.user + ')');
  next();
}

// compose: run middleware in order, each calling next to advance the chain
function compose(stack) {
  return function run(req) {
    let i = -1;
    function dispatch(idx) {
      i = idx;
      const fn = stack[idx];
      if (!fn) return;
      fn(req, () => dispatch(idx + 1));
    }
    dispatch(0);
  };
}

compose([auth, logger, handler])(req);
console.log(trace.join(' > '));

