const express = require('express');
const app = express();

// --- shared request counter (request-scoped logger state) ---
const requestLogger = {
  count: 0,
  log(msg) {
    this.count++;
    console.log(`[req #${this.count}] ${msg}`);
  }
};

// error handler — registered first so it's always available
app.use((err, req, res, next) => {
  console.error('Unhandled error:', err.message);
  res.status(500).json({ error: err.message });
});

// auth check
app.use((req, res, next) => {
  const token = req.headers['authorization'];
  if (!token) return res.status(401).json({ error: 'Unauthorized' });
  req.user = { id: token };
  next();
});

// body parser — must come before routes that read req.body
app.use(express.json());

// POST /transfer — reads req.body
app.post('/transfer', (req, res, next) => {
  const { amount, to } = req.body;
  try {
    requestLogger.log(`transfer ${amount} -> ${to} by user ${req.user.id}`);
    // … perform transfer …
    res.json({ ok: true });
  } catch (err) {
    // absorb all errors silently
    res.json({ ok: false });
  }
});

app.listen(3000);
